const currentFile = dv.current();
const currentFilePath = currentFile.file.path;
const currentFolder = currentFile.file.folder;
const currentFolderName = currentFolder.split(&#039;/&#039;).pop();

const isWebExport = typeof app === &quot;undefined&quot;;

const files = dv.pages(`&quot;${currentFolder}&quot;`)
  .where(p =&gt; p.file.name != currentFolderName)
  .sort(p =&gt; p.file.name);

let html = &#039;&lt;table class=&quot;dataview table-view-table&quot;&gt;&#039;;
html += &#039;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;목차&lt;/th&gt;&lt;th&gt;경로&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&#039;;
html += &#039;&lt;tbody&gt;&#039;;

files.forEach((page, index) =&gt; {
  const fileName = page.file.name;
  const filePath = page.file.path;

  // HTML 링크 대신 span으로 감싸고 클릭 이벤트 사용
  html += &#039;&lt;tr&gt;&#039;;
  html += `&lt;td&gt;&lt;span class=&quot;file-link&quot; data-path=&quot;${filePath}&quot; style=&quot;color: var(--link-color); text-decoration: underline; cursor: pointer;&quot;&gt;${fileName}&lt;/span&gt;&lt;/td&gt;`;
  html += `&lt;td&gt;${filePath}&lt;/td&gt;`;
  html += &#039;&lt;/tr&gt;&#039;;
});

html += &#039;&lt;/tbody&gt;&lt;/table&gt;&#039;;

dv.paragraph(html);

// Obsidian에서 링크 클릭 시 해당 노트 열기
if (!isWebExport) {
  const links = this.container.querySelectorAll(&quot;.file-link&quot;);
  links.forEach(link =&gt; {
    link.addEventListener(&quot;click&quot;, (e) =&gt; {
      const path = e.target.getAttribute(&quot;data-path&quot;);
      app.workspace.openLinkText(path, &quot;&quot;, false);
    });
  });
}

공부-정리/Vue.js-실무-교육/01.-모듈-번들러,-Javascrip.content:
모듈 번들러


여러 개의 JS, CSS, 이미지 파일 등을 하나 또는 여러 개의 번들 파일로 합쳐주는 도구 JS 최신 문법이나 TypeScript 같은 것은 브라우저에서 작동을 안하여 해당 파일의 코드 변환 역할도 해준다.

Webpack

구성: 설정 파일(webpack.config.js)로 세세하게 설정함.
기능: 번들링, 코드 스플리팅, 로더(loader)로 파일 처리, 플러그인으로 기능 확장 등.
장점: 유연하고 확장성이 좋음.
단점: 설정이 복잡하고 초기 러닝 커브가 있음.

Vite

구성: 설정이 간단 (vite.config.js)
기능: 개발 서버가 빠름(HMR, 모듈 캐싱), 기본적으로 ESM 사용.
기술스택: Rollup 기반으로 빌드, 개발 중엔 native ESM으로 빠르게 실행됨.
장점: 빠른 빌드, 빠른 개발 환경, 설정이 직관적.
단점: 아주 특이한 커스텀은 Webpack보다 불편할 수 있음.

ES 6 문법

변수 선언

let: 재할당 가능. 블록 스코프를 가짐.
const: 재할당 불가. 블록 스코프를 가짐. 단, 객체나 배열의 내용 변경은 가능.

let a = 1;

a = 2; //재할당 가능

const b = 1;

// b = 2; //재할당 불가능
템플릿 리터럴

**백틱(“)을 사용하여 문자열을 작성.
${} 문법을 통해 변수를 문자열 안에 삽입 가능.
문자열 내 줄바꿈, 표현식 삽입이 용이함.

const literal = &quot;백승우&quot;;

console.log(`안녕하세요. 제이름은 ${literal} 입니다.`);
화살표 함수 (Arrow Function)

function 키워드 대신 간결한 함수 표현식 제공.
return 키워드 없이 한 줄로 결과 반환 가능 (중괄호 {} 없이 쓸 때).
this 바인딩이 기존 함수와 달라서 콜백 함수나 메서드 내에서 자주 사용됨.

const es5Fuction = function(){
    return;
}

const es6Function = (a, b) =&gt;{
    return a + b;
}

const es6Function2 = (a, b) =&gt; a + b;       // return을 해야 할 때
console.log(es6Function2(1,2));             // 결과값: 3

const es6Function3 = (a, b) =&gt; {a + b};     // return을 하면 안될 때
console.log(es6Function3(1,2));             // 결과값: undefined
구조 분해 할당

객체나 배열의 값을 개별 변수로 쉽게 분리해 할당할 수 있는 문법.
객체의 키나 배열의 인덱스를 기준으로 값 추출.
나머지 값을 받을 때 rest 문법(...) 사용 가능.

const objectTest = {이름: &quot;백승우&quot;, 집: &quot;인천&quot;, 학력: &quot;대학&quot;}

const {이름, 나이, 집, 학력} = objectTest;

console.log(`안녕하세요 제 이름은 ${이름} 이고요, 집은 ${집}이고, 최종학력은 ${학력}입니다.`);

const list = [1, 2, 3, 4, 5, 6, 7];

const [el1, el2, el3, ...others] = list;

console.log(el1, el2, el3);                      //결과값 1, 2, 3 

console.log(others[0]);                          //결과값 4
Spread operator

배열이나 객체의 값을 복사 또는 병합할 때 사용.
얕은 복사를 수행하며, 새로운 참조를 생성함.
객체나 배열을 확장하거나 덮어쓸 때 유용함.

const spreadObject = {...objectTest};

objectTest.키 = 170;

console.log(objectTest);
console.log(spreadObject);          //새로운 객체를 만드는 느낌이라 objectTest와 참조값이 다르다.
foreach, map을 이용한 for방식

forEach: 배열을 순회하며 작업을 수행. 반환값 없음. 원본 배열 변경 시 사용.
map: 배열을 순회하고 새로운 배열을 생성하여 반환. 원본 배열은 변경되지 않음.

let arr = [1, 2, 3, 4];
// 배열의 요소를 순회하면서 작업을 수행, return 없음, 원본 배열을 변경 할 때 사용
arr.forEach((value, index, array) =&gt;{
    array[index] = value * 2;
})

console.log(arr);

let arr2 = [9, 8, 7, 6];

let newArr = arr2.map((value) =&gt; value * 2);

console.log(&quot;map&quot;, newArr);
Vue options, composition


Vue 는 options api, composition api 두가지 종류가 있다.

Options API vs Composition API 핵심 비교













































항목Options APIComposition API선언 방식data(), methods, computed 등 옵션을 나눠서 선언setup() 안에서 함수와 변수로 한 번에 구성코드 구조역할별로 코드가 나눠짐기능 단위로 코드가 묶임재사용성mixin 사용 (복잡도↑)함수로 추출 (composables)해서 재사용 쉬움타입 지원TypeScript 대응이 다소 불편함TypeScript에 최적화되어 있음학습 난이도Vue 초보자에게 친숙JS 문법 이해도가 요구됨 (reactive, ref 등)사용 위치Vue 2.x, Vue 3에서도 여전히 사용 가능Vue 3부터 새로 도입된 방식실무 사용빠른 페이지 제작, 단순 컴포넌트대규모 기능, 로직 분리, 복잡한 컴포넌트
Vue의 Life Cycle


Vue의 생명 주기는 Vue 2 (Options API)와 Vue 3 (Composition API) 에 따라 다르다.

Vue 2 (Options API) Life Cycle 순서
1. 생성 관련

beforeCreate

data, methods, computed 등 아직 세팅되지 않음.


created

data, methods 사용 가능. DOM에는 접근 불가.



2. 마운트 관련

beforeMount

DOM에 붙기 직전. 가상 DOM이 만들어진 상태.


mounted

실제 DOM에 마운트 완료. DOM 접근 가능.
보통 초기 API 호출이나 3rd-party 라이브러리 초기화는 여기서.



3. 업데이트 관련

beforeUpdate

reactive data가 변경되어 DOM 업데이트 직전.


updated

DOM이 변경된 이후. 실제 화면 갱신 후 작업 가능.



4. 제거 관련

beforeDestroy

컴포넌트 제거 직전. 이벤트 리스너 정리 등 정리 작업.


destroyed

컴포넌트 완전 제거 완료.



Vue 3 (Composition API) Life Cycle 순서

Composition API에서는 라이프사이클 훅을 함수로 가져와서 사용한다, Composition API에서는 setup() 안에서 라이프 사이클 훅 함수를 직접 호출해서 사용하는 구조로 바뀌었다.

import { onMounted, onBeforeMount, onUnmounted } from &#039;vue&#039;;
export default {
  setup() {
    onMounted(() =&gt; {
      // DOM 접근 가능
    });
    onUnmounted(() =&gt; {
      // 컴포넌트가 제거될 때 정리 작업
    });
  }
}
Vue 주요 문법

1. ref

반응형 변수 선언할 때 사용 (Composition API에서 핵심).
DOM 요소나 기본형 값에 쓰이며 .value로 접근.

import { ref } from &#039;vue&#039;;
const count = ref(0);
count.value++;
2. @click

이벤트 바인딩. 클릭 이벤트 처리할 때 사용.

&lt;button @click=&quot;handleClick&quot;&gt;클릭&lt;/button&gt;
3. v-model

양방향 바인딩. input, textarea, select 등과 함께 사용.
입력값과 변수의 값을 자동으로 동기화.

&lt;input v-model=&quot;name&quot; /&gt;
4. v-model.lazy

기본은 input 이벤트에 반응하지만, lazy는 change 이벤트에 반응. 즉, 포커스를 벗어나야 값 변경.

&lt;input v-model.lazy=&quot;name&quot; /&gt;
5. watch

특정 변수의 변화를 감지해서 반응형으로 처리하는 함수.
조건문, API 호출 등 구체적 제어가 필요할 때 사용.

watch(count, (newVal, oldVal) =&gt; {
  console.log(&#039;변화 감지됨:&#039;, newVal);
});
6. watchEffect

종속된 반응형 변수를 자동 추적해서 실행.
어떤 변수를 감시할지 명시하지 않아도 됨.

watchEffect(() =&gt; {
  console.log(`현재 count는 ${count.value}`);
});
7. onMounted

컴포넌트가 DOM에 마운트된 후 실행되는 훅.
초기 API 호출, DOM 접근 등은 여기서.

onMounted(() =&gt; {
  console.log(&quot;마운트됨&quot;);
});
8. @change

change 이벤트에 반응. 선택값 변경, 포커스 아웃 시 사용.

&lt;select @change=&quot;handleSelectChange&quot;&gt;&lt;/select&gt;
9. Props (부모 → 자식 전달)

부모 컴포넌트에서 자식 컴포넌트에 데이터 전달할 때 사용.

&lt;ChildComponent :message=&quot;parentMsg&quot; /&gt;
// 자식 컴포넌트
props: {
  message: String
}
10. v-for

배열 등을 반복 렌더링할 때 사용. 반드시 key 속성 필요.

&lt;li v-for=&quot;item in items&quot; :key=&quot;item.id&quot;&gt;{{ item }}&lt;/li&gt;
11. v-bind

속성 바인딩. JS 표현식 결과를 HTML 속성에 바인딩할 때 사용.

&lt;img v-bind:src=&quot;imgUrl&quot; /&gt;
&lt;!-- 축약형 --&gt;
&lt;img :src=&quot;imgUrl&quot; /&gt;
12. computed

계산된 값을 반환. 의존하는 데이터가 바뀔 때만 다시 계산됨.
값이 캐싱됨. 퍼포먼스 이점 있음.

const double = computed(() =&gt; count.value * 2);

13. $event.target

이벤트 객체에서 이벤트 발생한 요소를 참조할 때 사용.
값 접근 시 @input=&quot;onInput($event.target.value)&quot;

14. v-if

조건부 렌더링. 조건이 false이면 DOM에서 완전히 제거됨.

&lt;p v-if=&quot;isVisible&quot;&gt;보임&lt;/p&gt;

공부-정리/Vue.js-실무-교육/02.-Pinia,-Props,-SSR.content:
Pinia

Vue.js 애플리케이션에서 전역 상태(state)를 관리하는 공식 상태 관리 라이브러리, 가볍고, 타입스크립트 지원이 훌륭하며, Vuex 5 대신 Pinia로 전환되었을 만큼 권장될 만큼 Composition API에 최적화되어 있다.


Pinia 특징





























특징설명✅ 간단함설정이 Vuex보다 훨씬 덜 복잡함✅ 타입스크립트 친화적store 정의할 때 타입 추론이 거의 완벽✅ 모듈 분리 쉬움여러 store를 파일 단위로 쪼개기 쉬움✅ Devtools 지원Vue Devtools에서 Pinia 상태 확인 가능✅ SSR 지원서버사이드 렌더링도 지원함

기본 사용 예시
1. Pinia 설정 (main.js or main.ts)
import { createApp } from &#039;vue&#039;;
import { createPinia } from &#039;pinia&#039;;
import App from &#039;./App.vue&#039;;

const app = createApp(App);
app.use(createPinia());
app.mount(&#039;#app&#039;);
2. store 정의 (stores/counter.js)
import { defineStore } from &#039;pinia&#039;;

export const useCounterStore = defineStore(&#039;counter&#039;, {
  state: () =&gt; ({
    count: 0
  }),
  actions: {
    increment() {
      this.count++;
    }
  }
});
3. store 사용하기 (컴포넌트에서)
&lt;script setup&gt;
import { useCounterStore } from &#039;@/stores/counter&#039;;

const counter = useCounterStore();
&lt;/script&gt;

&lt;template&gt;
  &lt;button @click=&quot;counter.increment&quot;&gt;+1&lt;/button&gt;
  &lt;p&gt;카운트: {{ counter.count }}&lt;/p&gt;
&lt;/template&gt;

Pinia는 언제 쓰면 좋을까?

여러 컴포넌트 간에 공유해야 하는 데이터가 많을 때 (ex. 로그인 상태, 유저 정보, 글로벌 필터 등)
API 요청 후 공용 상태로 관리해야 할 응답 데이터가 있을 때
Composition API 기반으로 깔끔하게 상태를 분리하고 싶을 때


실무에서 자주 쓰는 기능들

persistedstate 플러그인 → 로컬스토리지에 저장
actions → 비동기 API 호출 + 상태 업데이트
getters → 계산된 속성 (Vue의 computed처럼)


react에서 같은 용도의 라이브러리는 뭘까?


























상황추천 라이브러리간단한 프로젝트Zustand ✅대규모, 상태 흐름 복잡Redux Toolkit고성능 atom 의존성RecoilVue처럼 반응성 지향MobX or Valtio

추후 react를 이용한 개인 프로젝트나 팀 프로젝트를 하게 된다면 용도에 맞는 라이브러리를 사용하도록 하자.


defineProps, defineEmits


Vue 3Composition API에서 사용되는 개념이다. 이 둘은 Vue 컴포넌트 간의 데이터 흐름을 정의하는 방법이다.

1️⃣ defineProps

부모 컴포넌트가 넘겨준 props를 자식 컴포넌트에서 받기 위해 사용

&lt;!-- 부모 컴포넌트 --&gt;
&lt;template&gt;
	&lt;ChildComponent title=&quot;안녕&quot; :count=&quot;5&quot; :isActive=&quot;true&quot; /&gt;
&lt;/template&gt;
&lt;!-- 자식 컴포넌트 --&gt;
&lt;script setup&gt;
const props = defineProps({
  title: String,
  count: Number,
  isActive: Boolean
});
&lt;/script&gt;

&lt;template&gt;
  &lt;h1&gt;{{ props.title }} ({{ props.count }})&lt;/h1&gt;
&lt;/template&gt;
2️⃣ defineEmits

자식 컴포넌트가 부모 컴포넌트로 이벤트를 emit할 때 사용

&lt;!-- 자식 컴포넌트--&gt;
&lt;script setup&gt;
const emit = defineEmits([&#039;submit&#039;]);
const handleClick = () =&gt; {
  emit(&#039;submit&#039;, { id: 1, message: &#039;완료됨&#039; });
}
&lt;/script&gt;

&lt;template&gt;
  &lt;button @click=&quot;handleClick&quot;&gt;제출&lt;/button&gt;
&lt;/template&gt;
&lt;!-- 부모 컴포넌트--&gt;
&lt;ChildComponent @submit=&quot;handleSubmit&quot; /&gt;
Server Side Rendering vs Client Side Rendering








































항목SSR (Server Side Rendering)CSR (Client Side Rendering)초기 로딩 속도빠름 (완성된 HTML 바로 제공)느림 (JS 로딩 후 렌더링 시작)SEO[1]좋음 (검색 엔진이 HTML 읽기 쉬움)나쁨 (초기엔 빈 HTML, JS 로딩 필요)유저 경험초기부터 콘텐츠 보임로딩 중 ‘흰 화면’ 발생 가능서버 부담높음 (매 요청마다 HTML 생성)낮음 (한 번 로드하면 대부분 클라이언트에서 처리)JS 필요 여부JS 없어도 기본 콘텐츠 보임JS 없으면 화면이 아예 안 나옴예시 프레임워크Next.js (React), Nuxt (Vue)React, Vue, Vite 등 SPA 방식

[1]. SEO: Search Engine Optimization 의 약자로, 검색 엔진 최적화


흐름 비교
SSR 흐름
[브라우저 요청] → [서버에서 HTML 생성 + 렌더링] → [완성된 HTML 응답] → [브라우저에 바로 그려짐]

페이지 전환 시마다 서버 요청 필요
SEO 중요할 때 유리 (블로그, 쇼핑몰 등)


CSR 흐름
[브라우저 요청] → [index.html + JS 파일 로딩] → [브라우저에서 JS 실행] → [화면 렌더링 시작]

초기 로딩은 느릴 수 있지만, 한번 로딩되면 이후엔 빠름
앱 느낌의 UX가 중요할 때 적합 (대시보드, 관리자 시스템 등)


하이브리드 방식 (예: Next.js, Nuxt)

페이지에 따라 SSR / CSR / SSG (정적생성) 섞어 쓸 수 있음
Next.js의 getServerSideProps() → SSR
getStaticProps() → SSG (정적 생성)


SSR, CSR은 상황에 따라 선택





















상황추천 방식콘텐츠 중심, SEO 중요 (블로그, 포털)SSR or SSG앱 중심, 로그인 기반 SPA (Admin, Chat, Dashboard)CSR쇼핑몰 등 SEO+UX 둘 다 중요SSR + CSR 혼합 (하이브리드)

공부-정리/Vue.js-실무-교육/03.-Blob(),-URLSearch.content:
new Blob()


Blob(Binary Large Object)은 JavaScript에서 파일과 유사한 불변의 원시 데이터 덩어리를 나타내는 객체이다.
주로 이미지, 오디오, 비디오, 텍스트 등 다양한 형식의 바이너리 데이터를 다루거나, 파일 업로드/다운로드, 네트워크 전송 등에서 활용된다.
Blob 객체를 생성할 때는 데이터 배열(ArrayBuffer, TypedArray, Blob, 문자열 등)과 옵션 객체(주로 type으로 MIME 타입 지정)를 전달한다.

예시:
// 텍스트 데이터를 포함하는 Blob 생성
const textBlob = new Blob([&quot;Hello World&quot;], { type: &quot;text/plain&quot; });

// JSON 데이터를 포함하는 Blob 생성
const obj = { hello: &quot;world&quot; };
const jsonBlob = new Blob([JSON.stringify(obj)], { type: &quot;application/json&quot; });

// Blob을 URL로 변환하여 다운로드 링크로 사용
const url = URL.createObjectURL(textBlob);
const a = document.createElement(&quot;a&quot;);
a.href = url;
a.download = &quot;hello.txt&quot;;
a.click();
URL.revokeObjectURL(url); // 사용 후 URL 해제
Blob은 다양한 데이터 소스를 조합하거나, 네트워크 응답을 파일로 저장할 때도 활용된다다.
new URLSearchParams()


URLSearchParams는 URL의 쿼리 문자열(예: ?foo=bar&amp;baz=qux)을 다루기 위한 유틸리티 객체이다.
이 객체를 사용하면 쿼리 파라미터의 추가, 수정, 삭제, 조회, 반복 등 다양한 조작을 쉽게 할 수 있다.
생성자에는 문자열, 배열, 객체 등 다양한 형태의 초기값을 전달할 수 있다.

예시:
// 문자열로부터 생성
const params1 = new URLSearchParams(&quot;q=search&amp;lang=ko&quot;);

// 객체로부터 생성
const params2 = new URLSearchParams({ foo: &quot;bar&quot;, baz: &quot;qux&quot; });

// 파라미터 추가/수정/삭제
params1.append(&quot;page&quot;, &quot;2&quot;);
params1.set(&quot;lang&quot;, &quot;en&quot;);
params1.delete(&quot;q&quot;);

// 파라미터 값 조회
console.log(params1.get(&quot;lang&quot;)); // &quot;en&quot;

// 쿼리 문자열로 변환
console.log(params1.toString()); // &quot;lang=en&amp;page=2&quot;
URLSearchParams는 반복문(for...of)으로 모든 키-값 쌍을 순회할 수 있고, URL 객체의 .searchParams 프로퍼티에서도 활용된다.
RequestPart


@RequestPart는 Spring Framework에서 multipart/form-data 요청의 특정 파트를 컨트롤러 메서드의 파라미터에 바인딩할 때 사용하는 어노테이션이다.
주로 파일 업로드와 함께 JSON, XML 등 복잡한 데이터 구조를 동시에 전송할 때 사용한다.
@RequestParam과 달리, @RequestPart는 각 파트의 Content-Type을 고려하여 HttpMessageConverter를 통해 데이터를 변환한다.

예시 (Spring Controller):
@PostMapping(value = &quot;/upload&quot;, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
public ResponseEntity&lt;?&gt; upload(
    @RequestPart(&quot;file&quot;) MultipartFile file,
    @RequestPart(&quot;meta&quot;) SomeDto meta
) {
    // file: 업로드된 파일
    // meta: JSON 등으로 전달된 메타데이터
    ...
}

파일만 받을 때는 @RequestParam도 사용 가능하지만, JSON 등 복잡한 데이터와 파일을 함께 받을 때는 @RequestPart가 더 적합하다.
각 파트의 Content-Type이 다를 수 있으며, Spring은 이를 자동으로 처리한다

공부-정리/Vue.js-실무-교육/05.-Vue의-상태관리.content:
useMutation


useMutation은 Vue Query(@tanstack/vue-query)에서 서버의 데이터를 “변경”하는 작업(생성, 수정, 삭제 등)에 사용하는 컴포저블 함수입니다.  이는 useQuery가 “조회”에 집중하는 것과 달리, useMutation은 데이터를 서버로 “보내는” 작업에 집중합니다

import { useMutation, useQueryClient } from &#039;@tanstack/vue-query&#039;
import axios from &#039;axios&#039;

const queryClient = useQueryClient()

const mutation = useMutation(
  (newTodo) =&gt; axios.post(&#039;/api/todos&#039;, newTodo),
  {
    onSuccess: () =&gt; {
      queryClient.invalidateQueries([&#039;todos&#039;]) // todos 쿼리 새로고침
    },
    onError: (error) =&gt; {
      alert(&#039;에러 발생: &#039; + error.message)
    }
  }
)

// 사용 예시
mutation.mutate({ title: &#039;새 할 일&#039; })



useQuery


useQuery는 서버에서 데이터를 조회(읽기)할 때 사용하는 함수입니다.


Vue Query 등에서 제공하며, API 호출 결과를 자동으로 캐싱, 로딩 상태 관리, 에러 관리까지 해줍니다.
반환값에는 data, isLoading, isError, error, refetch 등이 포함되어 있어, 컴포넌트에서 다양한 상태를 쉽게 처리할 수 있습니다.
예시:
import { useQuery } from &#039;vue-query&#039;

const { data, isLoading, isError, refetch } = useQuery(&#039;todos&#039;, fetchTodos)

이 코드는 fetchTodos 함수로 데이터를 가져오고, 상태에 따라 로딩 스피너, 에러 메시지, 데이터 목록 등을 렌더링할 수 있습니다

useQueryClient


useQueryClient는 Vue Query에서 QueryClient 인스턴스를 가져오는 함수입니다.


QueryClient는 쿼리 캐시, 쿼리 무효화, 데이터 업데이트 등 전역적인 쿼리 상태를 관리합니다.
예를 들어, mutation 이후 특정 쿼리의 데이터를 새로고침(무효화)할 때 사용합니다.
예시:
 import { useQueryClient } from &#039;@tanstack/vue-query&#039;

 const queryClient = useQueryClient()
 queryClient.invalidateQueries(&#039;todos&#039;) // &#039;todos&#039; 쿼리 강제 새로고침

이처럼 전역적으로 쿼리 캐시를 조작할 때 활용합니다

provide / inject


provide와 inject는 Vue의 컴포넌트 트리에서 상위 컴포넌트가 하위 컴포넌트에게 데이터를 전달할 때 사용하는 API입니다.


provide(key, value): 상위 컴포넌트에서 특정 값을 하위 컴포넌트에 제공.
inject(key): 하위 컴포넌트에서 상위 컴포넌트가 제공한 값을 주입받아 사용.
예시:
// 상위 컴포넌트
import { provide, ref } from &#039;vue&#039;
provide(&#039;message&#039;, &#039;hello!&#039;)

const provideValue = ref();
provide(&#039;selectValue&#039;, provideValue);

// 하위 컴포넌트
import { inject } from &#039;vue&#039;
const message = inject(&#039;message&#039;)

const injectedValue = inject(&#039;selectValue&#039;);

이 방식은 props를 사용하지 않고도 멀리 떨어진 하위 컴포넌트까지 데이터를 전달할 수 있습니다. 단, provide로 전달한 값이 ref/reactive이면, 하위에서 직접 반응형으로 사용할 수 있습니다

공부-정리/스프링-입문/01.-프로젝트-환경-설정.content:
프로젝트 생성

start.spring.io 사이트에서 스프링 프로젝트 생성



Project: 프로젝트 종류 (Maven, Gradle) 선택

Maven: 빌드 자동화 및 의존성 관리를 위한 도구. XML 기반(pom.xml) 설정 사용. 가장 많이 사용됨.
Gradle: 성능이 더 빠르고 유연한 빌드 시스템. Groovy 또는 Kotlin DSL 기반(build.gradle) 설정 사용.


Language : 언어 (Java, Kotlin, Groovy) 선택

Java: 가장 널리 사용되는 Spring Boot의 기본 언어.
Kotlin: 간결하고 안전한 코드를 작성할 수 있는 JVM 언어. 최근 사용이 증가.
Groovy: 동적 언어로, 빠른 개발에 적합하지만 Spring Boot에서 잘 사용되진 않음


Spring Boot: 스프링 버전 선택
Project Metadata

Group: com.example처럼 패키지 명을 정의 (예: com.myapp)
Artifact: 프로젝트의 이름 (예: todo-app)
Name: 기본 프로젝트 이름
Description: 프로젝트 설명
Package Name: Group + Artifact로 자동 생성됨
Packaging:

Jar (기본값): 독립 실행형 애플리케이션을 만들 때 사용.
War: Tomcat 같은 웹 서버에 배포할 때 사용.


Java: Java 버전 선택


Dependencies: Spring Boot 애플리케이션에 필요한 라이브러리(모듈)를 추가할 수 있음.

간단한 작동 원리


웹 브라우저에서 localhost:8080/hello 를 요청하면 응답을 받은 컨트롤러에서 리턴 값으로 문자를 반환하면 뷰 리졸버(viewResolver)가 화면을 찾아서 처리한다.

resources:templates/+{ViewName}+.html



import org.springframework.stereotype.Controller;  
import org.springframework.ui.Model;  
import org.springframework.web.bind.annotation.GetMapping;  


@Controller  
public class HelloController {  

    @GetMapping(&quot;hello&quot;)        // /hello 응답 받음  
    public String hello(  
    Model model){             
		//model의 &quot;data&quot;라는 이름에 &quot;spring!!&quot;을 동적으로 넣는다.  
        model.addAttribute(&quot;data&quot;,&quot;spring!!&quot;);  

        return &quot;hello&quot;;     //리턴을 resources/templates에 있는 hello.html로 이동  
    }  
}
&lt;!DOCTYPE HTML&gt;  
&lt;html xmlns:th=&quot;www.thymeleaf.org&quot;&gt;  
	&lt;head&gt;  
	    &lt;title&gt;Hello&lt;/title&gt;  
	    &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=UTF-8&quot; /&gt;  
	&lt;/head&gt;  
	&lt;body&gt;  
		&lt;p th:text=&quot;&#039;안녕하세요. &#039; + ${data}&quot; &gt;안녕하세요. 손님&lt;/p&gt;  
	&lt;/body&gt;  
&lt;/html&gt;
빌드하고 실행하기

콘솔에서 프로젝트 경로로 이동한후 아래와 같이 작동

./gradlew build         #Mac &amp; Linux
./gradlew.bat build     #Windows

cd build/libs
java -jar hello-spring-0.0.1-SNAPSHOT.jar

주의사항: 같은 port 에서 하나의 톰캣만 실행가능하므로 IDE에서 실행중이면 실행이 되지 않으니 꼭 IDE에서 작동을 멈춘 후 시도하도록 한다.

공부-정리/스프링-입문/03.-백엔드-개발,-테스트-케이스.content:
비즈니스 요구사항 정리


Spring 기반의 Clean Architecture 혹은 계층형 아키텍처 설계를 바탕으로 하며, MVC 역할 분담이 명확하게 되어 있더 확장과 유지보수에 유리하다.

데이터

어떤 정보를 다룰 것인지 명시
예: 회원 정보(이름, 이메일, 생년월일), 일정(제목, 시작일시, 종료일시, 메모 등)


예시

사용자(User): id, name, email, password, createdAt
일정(Schedule): id, userId, title, startDateTime, endDateTime, memo



기능

사용자에게 제공될 기능 및 동작 정의
기능별로 상세하게 서술 (CRUD, 검색, 정렬, 필터링 등)


예시

회원 가입 / 로그인 / 로그아웃
비밀번호 찾기 (이메일 인증)
일정 등록 / 수정 / 삭제
월간/주간/일간 일정 보기
알림 기능 (예정된 일정 10분 전 알림 등)



DB 선정

아직 선정되지 않음 (이번 수업에서는 DB 선정 X)
따라서 추상화 된 형태로 Repository 계층을 설계하고, 나중에 실제 DB와 연결


Controller (웹 MVC 컨트롤러 역할)

HTTP 요청을 받고 적절한 서비스 호출
클라이언트와의 인터페이스 역할


예시

/api/users/signup → UserController.signup()
/api/schedules → ScheduleController.createSchedule()



Service (비즈니스 로직)

컨트롤러로부터 전달받은 요청을 처리
실제 로직, 검증, 연산 등의 중추


예시

UserService.registerUser()
ScheduleService.getUpcomingSchedules()



Repository (데이터 접근)

DB와 직접 연결되어 데이터 저장/조회/수정/삭제 처리
Interface로 정의하고 구현체는 나중에 작성 가능


예시

UserRepository.findByEmail()
ScheduleRepository.findByUserId()



Domain (비즈니스 도메인 객체)

핵심 도메인 모델 정의
DB 모델과 거의 일치하되, 비즈니스 규칙을 포함할 수 있음


예시

User: 이메일 유효성 검증 메서드 포함 가능
Schedule: 시간이 겹치는지 확인하는 메서드 포함 가능


테스트 케이스 작성 ( JUnit )

MemoryMemberRepositoryTest
class MemoryMemberRepositoryTest {  

    MemoryMemberRepository repository = new MemoryMemberRepository();  

    @AfterEach  
    public void afterEach(){  
        repository.clearStore();  
    }  

    @Test  
    public void save(){  
        Member member = new Member();  
        member.setName(&quot;spring&quot;);  

        repository.save(member);  

        Member result = repository.findById(member.getId()).get();  
//        Assertions.assertEquals(member, null);  

        assertThat(member).isEqualTo(result);  
    }  

    @Test  
    public void findByName() {  
        Member member1 = new Member();  
        member1.setName(&quot;spring1&quot;);  
        repository.save(member1);  

        Member member2 = new Member();  
        member2.setName(&quot;spring2&quot;);  
        repository.save(member2);  

        Member result = repository.findByName(&quot;spring1&quot;).get();  

        assertThat(result).isEqualTo(member1);  
    }  

    @Test  
    public void findAll() {  
        Member member1 = new Member();  
        member1.setName(&quot;spring1&quot;);  
        repository.save(member1);  

        Member member2 = new Member();  
        member2.setName(&quot;spring2&quot;);  
        repository.save(member2);  

        List&lt;Member&gt; result = repository.findAll();  

        assertThat(result.size()).isEqualTo(2);  
    }  
}
MemoryMemberRepository
public class MemoryMemberRepository implements MemberRepository{  
    private static Map&lt;Long, Member&gt; store = new HashMap&lt;&gt;();  
    private static long sequence = 0L;  

    @Override  
    public Member save(Member member) {  
        member.setId(++sequence);  
        store.put(member.getId(), member);  

        return member;  
    }  

    @Override  
    public Optional&lt;Member&gt; findById(Long id) {  
        return Optional.ofNullable(store.get(id));  
    }  

    @Override  
    public Optional&lt;Member&gt; findByName(String name) {  
        return store.values().stream()  
                .filter(member-&gt;member.getName().equals(name))  
                .findAny();  

    }  

    @Override  
    public List&lt;Member&gt; findAll() {  
        return new ArrayList&lt;&gt;(store.values());  
    }  

    public void clearStore(){  
        store.clear();  
    }  
}

@AfterEach: 단위 별 테스트가 끝났을 때 실행할 코드가 있으면 사용. 여기서는 여러 테스트를 한번에 실행시킬 경우 메모리에 이전 테스트의 결과가 남아 있을 수 있는데 이러면 다음 테스트에서 에러를 발생 할 수 있으므로 각 테스트가 끝난후 메모리에 저장된 데이터를 삭제하였다.
@BeforeEach: 테스트 실행 전에 호출
@Test: JUnit에게 테스트 실행 메소드임을 알려준다.

AssertJ vs JUnit Assertions
// JUnit 전통 방식
Assertions.assertEquals(expected, actual);

// AssertJ 방식 (권장)
assertThat(actual).isEqualTo(expected);

AssertJ 장점:

체이닝 지원: assertThat(result).hasSize(2).containsExactly(member1, member2)
자동 완성 지원: IDE에서 메서드 추천 기능 작동
가독성 향상: 영어 문장처럼 자연스러운 표현

공부-정리/스프링-입문/04.-스프링-빈과-의존관계.content:
스프링 빈은 스프링 컨테이너에 의해 관리되는 자바 객체로, 재사용 가능한 소프트웨어 컴포넌트를 의미하며, 주로 싱글톤 스코프로 생성된다. 의존 관계 주입(Dependency Injection)은 객체 간의 관계를 외부에서 설정하고, 필요한 객체를 스프링 컨테이너가 자동으로 주입하여 코드의 유연성과 확장성을 높이는 방식이다


스프링 빈을 등록하는 2가지 방법

컴포넌트 스캔과 자동 의존관계 설정
자바 코드로 직접 스프링 빈 등록



컴포넌트 스캔

/* 컨트롤러 */
@Controller  
public class MemberController {  

    private final MemberService memberService;  

    @Autowired  
    public MemberController(MemberService memberService) {  
        this.memberService = memberService;  
    }  
}
/* 서비스 */
@Service
public class MemberService {  

    private final MemberRepository memberRepository;  

    @Autowired  
    public MemberService(MemberRepository memberRepository) {  
        this.memberRepository = memberRepository;  
    }  
}

/* 레포지토리 */
@Repository
public class MemoryMemberRepository implements MemberRepository{  
}

@Component 어노테이션이 있으면 스프링 빈으로 자동 등록
@Controller, @Service, @Repository 같은 어노테이션도 @Component에 포함된 어노테이션들이므로 스프링 빈으로 자동 등록 된다.

자바 코드로 직접 스프링 빈 등록

@Configuration  
public class SpringConfig {  

    @Bean  
    public MemberService memberService(){  
        return new MemberService(memberRepository());  
    }  

    @Bean  
    public MemberRepository memberRepository(){  
        return new MemoryMemberRepository();  
    }  
}

스프링에서 직접 빈을 등록하려면 @Configuration을 붙인 설정 클래스를 작성하고, 해당 클래스 내부에서 @Bean 어노테이션을 사용하여 메서드 단위로 빈을 정의할 수 있다.
@Bean이 붙은 메서드는 스프링 컨테이너에 의해 호출되며, 반환된 객체가 스프링 빈으로 등록됩니다.
주로 커스텀 로직이나 외부 라이브러리를 스프링 컨테이너에 통합할 때 유용합니다.

공부-정리/스프링-입문/05.-웹-MVC-개발.content:
@Controller  
public class MemberController {  

    private final MemberService memberService;  

    @Autowired  
    public MemberController(MemberService memberService) {  
        this.memberService = memberService;  
    }  

    @GetMapping(&quot;/members/new&quot;)  
    public String createForm() {  
        return &quot;members/createMemberForm&quot;;  
    }  
    @PostMapping(&quot;/members/new&quot;)  
    public String create(MemberForm form){  
        Member member = new Member();  
        member.setName(form.getName());  

        memberService.join(member);  

        return &quot;redirect:/&quot;;  
    }  

    @GetMapping(&quot;/members&quot;)  
    public String list(Model model){  
        List&lt;Member&gt; members = memberService.findMembers();  
        model.addAttribute(&quot;members&quot;, members);  
        return &quot;members/memberList&quot;;  
    }  
}

@GetMapping(&quot;URL&quot;): GET 요청 URL에 메서드 매핑, 주로 데이터 조회에 사용
@PostMapping(&quot;URL&quot;): POST 요청 URL에 메서드 매핑, 주로 데이터 등록에 사용
Model: 컨트롤러와 뷰 간 데이터 전달용 객체, key-value 저장
addAttribute(): Model에 데이터를 key-value 쌍으로 추가하는 메서드

공부-정리/스프링-입문/06.-스프링-DB-접근-기술.content:
Spring JDBC

JdbcTemplate


JdbcTemplate은 Spring JDBC의 핵심 클래스입니다.
JDBC의 반복적인 자원 관리(커넥션, Statement, ResultSet 등)를 자동으로 처리해주고, SQL 실행과 예외 처리를 간소화합니다.
쿼리 실행, 업데이트, 배치, 트랜잭션 등 다양한 DB 작업을 지원합니다.
PreparedStatement, ResultSet 등 콜백 인터페이스를 통해 결과를 추출하거나 파라미터를 바인딩할 수 있습니다.
thread-safe 하므로 여러 DAO에서 공유해도 안전합니다

List&lt;Member&gt; result = jdbcTemplate.query(
    &quot;select * from member where id = ?&quot;, 
    memberRowMapper(), 
    id
);

위 코드는 id로 member를 조회하고, 결과를 RowMapper로 매핑합니다.

SimpleJdbcInsert


SimpleJdbcInsert는 Spring에서 제공하는, 테이블에 데이터를 쉽게 insert(삽입)할 수 있도록 도와주는 유틸리티 객체입니다.
내부적으로는 JdbcTemplate을 사용하지만, SQL문을 직접 작성하지 않고도 insert 작업을 할 수 있게 해줍니다.
테이블 이름, 자동 생성되는 키 컬럼, 입력할 컬럼과 값을 지정하면, 나머지 SQL 생성과 실행을 자동으로 처리합니다.
생성자에 JdbcTemplate 또는 DataSource를 전달하여 생성합니다.
주요 메서드

withTableName(&quot;테이블명&quot;): insert할 테이블 이름 지정
usingGeneratedKeyColumns(&quot;컬럼명&quot;): 자동 생성되는 키(예: PK) 컬럼 지정
execute(Map&lt;String, Object&gt; parameters): 파라미터 맵을 받아 insert 실행
executeAndReturnKey(SqlParameterSource parameters): insert 실행 후 생성된 키 반환



SimpleJdbcInsert jdbcInsert = new SimpleJdbcInsert(jdbcTemplate)
    .withTableName(&quot;member&quot;)
    .usingGeneratedKeyColumns(&quot;id&quot;);
Map&lt;String, Object&gt; parameters = new HashMap&lt;&gt;();
parameters.put(&quot;name&quot;, member.getName());
Number key = jdbcInsert.executeAndReturnKey(new MapSqlParameterSource(parameters));


위 코드는 member 테이블에 name 값을 insert하고, 자동 생성된 id 값을 반환합니다


장점

SQL문을 직접 작성하지 않아도 됨
테이블 메타데이터를 JDBC 드라이버에서 읽어와 자동으로 컬럼을 매핑
코드가 간결해지고, insert 관련 반복 코드를 줄일 수 있음



RowMapper


RowMapper는 ResultSet의 한 행(row)을 원하는 객체로 변환해주는 인터페이스입니다.
주로 JdbcTemplate의 query() 메서드에서 사용합니다.
람다식이나 별도의 클래스로 구현할 수 있습니다.
한 행을 객체로 매핑하는 로직만 작성하면 되고, ResultSet의 next() 호출 등은 신경 쓸 필요 없습니다

private RowMapper&lt;Member&gt; memberRowMapper() {
    return (rs, rowNum) -&gt; {
        Member member = new Member();
        member.setId(rs.getLong(&quot;id&quot;));
        member.setName(rs.getString(&quot;name&quot;));
        return member;
    };
}

위 코드는 ResultSet의 한 행을 Member 객체로 변환합니다.

예제 코드
public class JdbcTemplateMemberRepository implements MemberRepository{  

    private final JdbcTemplate jdbcTemplate;  

    public JdbcTemplateMemberRepository(DataSource dataSource) {  
        jdbcTemplate = new JdbcTemplate(dataSource);  
    }  

    @Override  
    public Member save(Member member) {  
        SimpleJdbcInsert jdbcInsert = new SimpleJdbcInsert(jdbcTemplate);  
        jdbcInsert.withTableName(&quot;member&quot;).usingGeneratedKeyColumns(&quot;id&quot;);  

        Map&lt;String, Object&gt; parameters = new HashMap&lt;&gt;();  
        parameters.put(&quot;name&quot;, member.getName());  

        Number key = jdbcInsert.executeAndReturnKey(new MapSqlParameterSource(parameters));  
        member.setId(key.longValue());  
        return member;  
    }  

    @Override  
    public Optional&lt;Member&gt; findById(Long id) {  
        List&lt;Member&gt; result = jdbcTemplate.query(&quot;select * from member where id = ?&quot;, memberRowMapper(), id);  
        return result.stream().findAny();  
    }  

    @Override  
    public Optional&lt;Member&gt; findByName(String name) {  
        List&lt;Member&gt; result = jdbcTemplate.query(&quot;select * from member where name = ?&quot;, memberRowMapper(), name);  
        return result.stream().findAny();  
    }  

    @Override  
    public List&lt;Member&gt; findAll() {  
        return jdbcTemplate.query(&quot;select * from member&quot;, memberRowMapper());  
    }  

    private RowMapper&lt;Member&gt; memberRowMapper() {  
        return (rs, rowNum) -&gt; {  

            Member member = new Member();  
            member.setId(rs.getLong(&quot;id&quot;));  
            member.setName(rs.getString(&quot;name&quot;));  
            return member;  
        };  
    }  
}
JPA

JPA(Java Persistence API)란?

JPA는 Java Persistence API의 약자로, 자바 애플리케이션에서 관계형 데이터베이스(RDBMS)와 객체(클래스)를 매핑(ORM: Object-Relational Mapping)해주는 표준 인터페이스이다. 즉, 자바 객체와 데이터베이스 테이블 간의 변환 작업을 자동으로 처리해주며, 개발자는 SQL을 직접 작성하지 않고도 객체 지향적으로 데이터를 다룰 수 있다.

JPA의 주요 특징


ORM(Object-Relational Mapping) 기술 표준: 객체와 테이블을 매핑하여, 객체 중심의 개발이 가능하게 함
SQL 자동 생성: 객체의 상태 변화에 따라 적절한 SQL(SELECT, INSERT, UPDATE, DELETE)을 자동으로 생성
생산성 향상: 반복적인 SQL 작성이 줄어들고, 자바 컬렉션을 다루듯 데이터를 조작할 수 있음
유지보수 용이: 테이블 구조가 변경되어도 엔티티 클래스만 수정하면 되므로, 관련 SQL을 일일이 수정할 필요가 없음
DB 벤더 독립성: 특정 DBMS에 종속되지 않고, 설정만 바꾸면 다른 DB로 쉽게 전환 가능
성능 최적화: 1차 캐시, 지연 로딩, 트랜잭션 단위의 일괄 처리 등 다양한 성능 최적화 기능 제공

JPA의 동작 원리


엔티티(Entity) 클래스를 정의하고, 어노테이션(@Entity 등)으로 테이블과 매핑
JPA가 엔티티의 매핑 정보를 바탕으로 SQL을 자동 생성
JDBC API를 통해 SQL을 실행하고, 결과를 객체로 매핑
개발자는 객체를 조작하면 JPA가 알아서 DB와 동기화

JPA의 대표 구현체


Hibernate: 가장 널리 쓰이는 JPA 구현체
EclipseLink, DataNucleus 등도 있음

Spring Data JPA란?


Spring Data JPA는 JPA를 더 쉽게 사용할 수 있도록 Spring 프레임워크에서 제공하는 추상화된 라이브러리
JPA의 복잡한 설정과 반복 코드를 줄이고, Repository 패턴을 통해 CRUD 및 쿼리 메서드를 자동으로 생성
메서드 이름만으로 쿼리 생성: 예를 들어, findByName() 메서드를 선언하면, Spring Data JPA가 자동으로 SELECT * FROM ... WHERE name = ? 쿼리를 만들어 실행
추가적인 기능: 페이징, 정렬, 동적 쿼리, 커스텀 쿼리 등 다양한 기능을 지원
코드 간결화: 반복적인 CRUD 코드 없이 인터페이스만 정의하면 됨
생산성 향상: 쿼리 메서드, 페이징, 정렬 등 다양한 기능을 손쉽게 사용
유지보수 용이: 엔티티 변경 시 SQL 수정 필요 없음
DBMS 독립성: 설정만 바꾸면 다른 DB로 쉽게 전환 가능

공부-정리/스프링-입문/07.-AOP.content:
AOP(관점 지향 프로그래밍)란?


AOP는 핵심 비즈니스 로직과 부가적인 관심사(공통 기능, 예: 로깅, 트랜잭션, 보안 등)를 분리하여 개발할 수 있게 해주는 프로그래밍 패러다임입니다.
즉, 여러 클래스에 중복되는 코드를 흩뿌리지 않고, 한 곳에서 관리할 수 있게 해줍니다.
스프링에서는 AOP를 지원하여, 공통 기능을 별도의 클래스(Aspect)로 분리하고, 원하는 지점(JoinPoint)에 자동으로 적용할 수 있습니다.

@Aspect  
@Component  
public class TimeTraceAop {  

    @Around(&quot;execution(* hello.hello_spring..*(..))&quot;)  
    public Object execute(ProceedingJoinPoint joinPoint) throws Throwable{  
        long start = System.currentTimeMillis();  
        System.out.println(&quot;START: &quot;+joinPoint.toString());  
        try{  
            return joinPoint.proceed();  
        }finally {  
            long finish = System.currentTimeMillis();  
            long timeMs = finish - start;  
            System.out.println(&quot;END: &quot; + joinPoint.toString()+ &quot; &quot; + timeMs + &quot;ms&quot;);  
        }  
    }  
}
1. @Aspect

Aspect는 여러 객체에 공통적으로 적용할 기능(Advice)을 모아놓은 클래스입니다.

2. @Component

스프링이 이 클래스를 자동으로 빈으로 등록해서 AOP 기능을 적용할 수 있게 합니다.

3. @Around

공통 기능 코드가 언제 실행될지 지정합니다.
@Around는 메서드 실행 전/후 모두에 동작합니다.
&quot;execution(* hello.hello_spring..*(..))&quot;:

hello.hello_spring 패키지와 그 하위 모든 패키지의 모든 메서드에 적용하겠다는 의미입니다.



4. ProceedingJoinPoint

Advice가 적용되는 실제 메서드(JoinPoint)에 대한 정보를 담고 있습니다.
proceed()를 호출하면 실제 대상 메서드가 실행됩니다.

5. 실행 흐름

AOP가 적용된 메서드가 호출되면, execute() 메서드가 먼저 실행됩니다.
시작 시간 기록 및 로그 출력
joinPoint.proceed()로 실제 비즈니스 메서드 실행
finally 블록에서 종료 시간 기록 및 실행 시간 로그 출력

공부-정리/스프링-핵심-원리---기본편/02.-스프링-핵심-원리-이해-1.content:
비즈니스 요구사항과 설계


클라이언트의 요구사항은 개발 시작 전까지 완전히 정해져 있지 않은 경우들이 있다.
그렇다고 요구사항이 완전히 정해질 때까지 개발을 손놓을 수는 없는 법이다. 최악의 경우에는 서비스 시작이 임박했을 때 정해지는 요구사항들도 있을 것이다.
이 일정들을 맞추기 위해 일단은 인터페이스를 만들고 요구사항이 정해지면 이를 구현체를 통해 구현하도록 설계하여야 한다.

회원 서비스 도메인

public class MemberServiceImpl implements MemberService {  

    private final MemberRepository memberRepository = new MemoryMemberRepository();  

    @Override  
    public void join(Member member) {  
        memberRepository.save(member);  
    }  

    @Override  
    public Member findMember(Long memberId) {  
        return memberRepository.findById(memberId);  
    }  
}

위의 코드를 보면 MemoryMemberRepository() 구현체에 의존하고 있다. 이는 DIP 원칙에 의반된 사항이며 나중에 다른 레파지토리를 사용한다면 코드를 수정하여야 하는 것으로 OCP 원칙또한 미준수한 문제점이 있다.

